import os
import boto3

def get_polly_client():
    return boto3.client('polly',
                        region_name='us-west-2',
                        aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
                        aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'))

def synthesize_speech(text, voice_id, output_format='mp3'):
    polly_client = get_polly_client()
    response = polly_client.synthesize_speech(Text=text,
                                              VoiceId=voice_id,
                                              OutputFormat=output_format)
    return response['AudioStream'].read()

import boto3

def save_audio(text, output_file):
    polly_client = boto3.client('polly')
    response = polly_client.synthesize_speech(
        Text=text,
        OutputFormat='mp3',
        VoiceId='Joanna'
    )
    if 'AudioStream' in response:
        with open(output_file, 'wb') as file:
            file.write(response['AudioStream'].read())
    else:
        raise Exception('AudioStream not found in response')

import boto3

def list_voices():
    polly_client = boto3.client('polly')
    voices = polly_client.describe_voices()
    return voices['Voices']

def select_voice(language_code):
    voices = list_voices()
    for voice in voices:
        if voice['LanguageCode'] == language_code:
            return voice['Id']
    return None
